// The web server's client for the bjk-core API. The calls and types are generated by NSwag from the API itself
// (./generated/api.ts, rebuilt with the API: see src/BJK.Core.Api/nswag.json), so they can't drift from it. This file
// only adds what the generated client can't know: each call takes the caller's access token explicitly (null for
// anonymous reads), so it's easy to test and never reads cookies itself; anonymous reads can use the Next.js data
// cache; and failures throw ApiError with the API's problem details. Only the web server uses it: the browser never
// sees access tokens.

import {
  AreaClient,
  DraftsClient,
  EngagementClient,
  HashtagsClient,
  HeatmapClient,
  MediaClient,
  NotificationsClient,
  PlacesClient,
  PostsClient,
  ProfilesClient,
  ReelsClient,
  ReportsClient,
  TimelinesClient,
  TrendsClient,
  VehiclesClient,
} from "./generated/api";
import type {
  AreaAlertMode,
  CommentSetting,
  HeatmapQuery,
  IncidentCategory,
  NotificationSettingDto,
  PassengerTagStatus,
  ProblemDetails,
  PublicReportRequest,
  ReactionType,
  SaveDraftRequest,
  ReportReason,
  TimelineRequest,
  VoteChoice,
  VoteDuration,
} from "./types";
import type { CreatePostRequest } from "./types";

export const AGE_VERIFICATION_REQUIRED = "age_verification_required";
export const DAILY_LIMIT = "daily_limit";

/** The header the API counts logged-out reel plays by (the value comes from the signed bjk_viewer cookie). */
export const VIEWER_ID_HEADER = "X-Viewer-Id";

/** The API answered with an error. `problem` is its RFC 7807 body when it sent one. */
export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly problem: ProblemDetails | undefined,
    readonly path: string,
    /** The API's WWW-Authenticate header on a 401: says why a token was refused (expired, wrong issuer, etc.). */
    readonly authenticate?: string,
  ) {
    super(problem?.detail || problem?.title || `The API returned ${status} for ${path}.`);
    this.name = "ApiError";
  }

  get code(): string | undefined {
    return this.problem?.code;
  }

  get isAgeCheckNeeded(): boolean {
    return this.status === 403 && this.code === AGE_VERIFICATION_REQUIRED;
  }

  /** Today's reels are used up (403 daily_limit). */
  get isDailyLimit(): boolean {
    return this.status === 403 && this.code === DAILY_LIMIT;
  }

  /** Validation messages by field, camel-cased ("Title" becomes "title"). */
  get fieldErrors(): Record<string, string[]> {
    const errors = this.problem?.errors ?? {};
    return Object.fromEntries(
      Object.entries(errors).map(([key, messages]) => [
        key ? key[0]!.toLowerCase() + key.slice(1) : "",
        messages,
      ]),
    );
  }

  /** One sentence to show the person: the first validation message, or the problem's detail. */
  get userMessage(): string {
    const first = Object.values(this.problem?.errors ?? {})[0]?.[0];
    if (first) {
      return first;
    }
    if (this.problem?.detail) {
      return this.problem.detail;
    }
    if (this.status === 401) {
      return "Please sign in again.";
    }
    if (this.status === 404) {
      return "We couldn't find that. It may have been removed.";
    }
    if (this.status === 429) {
      return "You're doing that too often. Please wait a little and try again.";
    }
    return "Something went wrong. Please try again.";
  }
}

export interface RequestOptions {
  token?: string | null;
  headers?: Record<string, string>;
  /** Cache anonymous reads for this many seconds (Next.js data cache). Ignored when there's a token. */
  revalidate?: number;
}

/** What the generated clients call instead of fetch: adds the token and caching, and turns failures into ApiError. */
interface Http {
  fetch(url: RequestInfo, init?: RequestInit): Promise<Response>;
}

export interface ApiClient {
  /** The base address the generated clients are pointed at. */
  readonly baseUrl: string;
  /** A fetch for one call, carrying that call's token, headers and caching. */
  http(options?: RequestOptions): Http;
}

export function createApiClient(baseUrl: string, fetchImpl: typeof fetch = fetch): ApiClient {
  const base = baseUrl.replace(/\/+$/, "");
  return {
    baseUrl: base,
    http(options: RequestOptions = {}): Http {
      return {
        async fetch(input: RequestInfo, init: RequestInit = {}): Promise<Response> {
          const url = new URL(typeof input === "string" ? input : input.url);
          const path = url.pathname;
          const method = (init.method ?? "GET").toUpperCase();

          const headers: Record<string, string> = {
            Accept: "application/json",
            ...(init.headers as Record<string, string> | undefined),
            ...options.headers,
          };
          if (options.token) {
            headers.Authorization = `Bearer ${options.token}`;
          }

          // Next.js adds `next` (data cache options) to RequestInit.
          const request: RequestInit = { ...init, method, headers };
          if (!options.token && options.revalidate && method === "GET") {
            request.next = { revalidate: options.revalidate };
          } else {
            request.cache = "no-store";
          }

          const response = await fetchImpl(url, request);
          if (!response.ok) {
            let problem: ProblemDetails | undefined;
            try {
              problem = (await response.json()) as ProblemDetails;
            } catch {
              problem = undefined;
            }
            throw new ApiError(
              response.status,
              problem,
              path,
              response.headers.get("www-authenticate") ?? undefined,
            );
          }
          return response;
        },
      };
    },
  };
}

type ClientType<T> = new (baseUrl?: string, http?: Http) => T;

export interface FeedQuery {
  category?: IncidentCategory;
  author?: string;
  /** Only posts with this hashtag (without the #). */
  hashtag?: string;
  page?: number;
  pageSize?: number;
}

/** The API's endpoints, by module, over the generated clients. */
export function endpoints(api: ApiClient) {
  const client = <T>(type: ClientType<T>, options: RequestOptions = {}) =>
    new type(api.baseUrl, api.http(options));
  const posts = (token: string | null, revalidate?: number) => client(PostsClient, { token, revalidate });
  const profiles = (token: string | null) => client(ProfilesClient, { token });
  const viewer = (viewerId: string | null) => (viewerId ? { [VIEWER_ID_HEADER]: viewerId } : undefined);

  return {
    posts: {
      list: (token: string | null, q: FeedQuery = {}, revalidate?: number) =>
        posts(token, revalidate).posts_List(
          undefined,
          q.category,
          q.author,
          undefined,
          undefined,
          undefined,
          q.page ?? 1,
          q.pageSize ?? 20,
          q.hashtag,
        ),
      mine: (token: string, page = 1, pageSize = 20) => posts(token).posts_ListMine(page, pageSize),
      /** One person's comments and replies, with the post each is on (their profile's Replies tab). */
      replies: (token: string, handle: string, page = 1, pageSize = 20) =>
        posts(token).posts_ListProfileReplies(handle, page, pageSize),
      get: (token: string | null, postId: string) => posts(token).posts_Get(postId),
      create: (token: string, body: CreatePostRequest) => posts(token).posts_Create(body),
      remove: (token: string, postId: string) => posts(token).posts_Delete(postId),
      react: (token: string, postId: string, type: ReactionType) =>
        posts(token).posts_React(postId, { type }),
      unreact: (token: string, postId: string) => posts(token).posts_RemoveReaction(postId),
      report: (token: string, postId: string, reason: ReportReason, details: string | null) =>
        posts(token).posts_ReportPost(postId, { reason, details }),
      appeal: (token: string, postId: string, statement: string) =>
        posts(token).posts_AppealPost(postId, { statement }),
      tagged: (token: string, status: PassengerTagStatus = "Pending", page = 1, pageSize = 20) =>
        posts(token).posts_ListTagged(status, page, pageSize),
      respondToTag: (token: string, postId: string, accept: boolean) =>
        posts(token).posts_RespondToTag(postId, { accept }),
      removeMyTag: (token: string, postId: string) => posts(token).posts_RemoveMyTag(postId),
      /** On your own post: who can comment (everyone, or nobody). */
      setCommentSetting: (token: string, postId: string, setting: CommentSetting) =>
        posts(token).posts_SetCommentSetting(postId, { setting }),
    },
    engagement: {
      /** Vote on a post, or change your vote, until it closes. */
      vote: (token: string, postId: string, choice: VoteChoice) =>
        client(EngagementClient, { token }).engagement_Vote(postId, { choice }),
      follow: (token: string, postId: string) =>
        client(EngagementClient, { token }).engagement_Follow(postId),
      unfollow: (token: string, postId: string) =>
        client(EngagementClient, { token }).engagement_Unfollow(postId),
      save: (token: string, postId: string) => client(EngagementClient, { token }).engagement_Save(postId),
      unsave: (token: string, postId: string) =>
        client(EngagementClient, { token }).engagement_Unsave(postId),
      bookmarks: (token: string, page = 1, pageSize = 20) =>
        client(EngagementClient, { token }).engagement_Bookmarks(page, pageSize),
      /** Count that the viewer saw these posts (once per viewer per post). Signed-out viewers by their viewer id. */
      views: (token: string | null, viewerId: string | null, postIds: string[]) =>
        client(EngagementClient, { token, headers: viewer(viewerId) }).engagement_RecordViews({ postIds }),
      /** Count a share (once per viewer per post per day). */
      share: (token: string | null, viewerId: string | null, postId: string) =>
        client(EngagementClient, { token, headers: viewer(viewerId) }).engagement_RecordShare(postId),
      /** Views, local views, reactions, comments and shares: the author only. */
      reach: (token: string, postId: string) => client(EngagementClient, { token }).engagement_Reach(postId),
      preferences: (token: string) => client(EngagementClient, { token }).engagement_GetPreferences(),
      setVoteDuration: (token: string, voteDuration: VoteDuration) =>
        client(EngagementClient, { token }).engagement_SetPreferences({ voteDuration }),
    },
    drafts: {
      list: (token: string) => client(DraftsClient, { token }).drafts_List(),
      get: (token: string, draftId: string) => client(DraftsClient, { token }).drafts_Get(draftId),
      create: (token: string, body: SaveDraftRequest) => client(DraftsClient, { token }).drafts_Create(body),
      update: (token: string, draftId: string, body: SaveDraftRequest) =>
        client(DraftsClient, { token }).drafts_Update(draftId, body),
      remove: (token: string, draftId: string) => client(DraftsClient, { token }).drafts_Delete(draftId),
    },
    comments: {
      list: (token: string, postId: string, page = 1, pageSize = 20) =>
        posts(token).posts_ListComments(postId, page, pageSize),
      replies: (token: string, postId: string, commentId: string, page = 1, pageSize = 50) =>
        posts(token).posts_ListReplies(postId, commentId, page, pageSize),
      add: (token: string, postId: string, body: string) => posts(token).posts_AddComment(postId, { body }),
      reply: (token: string, postId: string, commentId: string, body: string) =>
        posts(token).posts_Reply(postId, commentId, { body }),
      edit: (token: string, postId: string, commentId: string, body: string) =>
        posts(token).posts_EditComment(postId, commentId, { body }),
      remove: (token: string, postId: string, commentId: string) =>
        posts(token).posts_DeleteComment(postId, commentId),
      /** The text now and before each edit, newest first. */
      history: (token: string, postId: string, commentId: string) =>
        posts(token).posts_GetCommentHistory(postId, commentId),
      /** On your own post: hide someone's comment from everyone else, or show it again. */
      setHidden: (token: string, postId: string, commentId: string, hidden: boolean) =>
        posts(token).posts_SetCommentHidden(postId, commentId, { hidden }),
      react: (token: string, postId: string, commentId: string, type: ReactionType) =>
        posts(token).posts_ReactToComment(postId, commentId, { type }),
      unreact: (token: string, postId: string, commentId: string) =>
        posts(token).posts_RemoveCommentReaction(postId, commentId),
      report: (
        token: string,
        postId: string,
        commentId: string,
        reason: ReportReason,
        details: string | null,
      ) => posts(token).posts_ReportComment(postId, commentId, { reason, details }),
      appeal: (token: string, postId: string, commentId: string, statement: string) =>
        posts(token).posts_AppealComment(postId, commentId, { statement }),
    },
    reports: {
      /** The public form. `clientIp` is the visitor's address, passed on as Cloudflare would. */
      submitPublic: (body: PublicReportRequest, captchaToken: string, clientIp?: string | null) =>
        client(ReportsClient, {
          headers: clientIp ? { "CF-Connecting-IP": clientIp } : undefined,
        }).reports_ReportPublicly(body, captchaToken),
      profile: (token: string, handle: string, reason: ReportReason, details: string | null) =>
        client(ReportsClient, { token }).reports_ReportProfile(handle, { reason, details }),
    },
    profiles: {
      me: (token: string) => profiles(token).profiles_GetMine(),
      get: (token: string | null, handle: string) => profiles(token).profiles_GetByHandle(handle),
      create: (
        token: string,
        body: { handle: string; displayName: string; bio: string | null; location: string | null },
      ) => profiles(token).profiles_Create(body),
      update: (token: string, body: { displayName: string; bio: string | null; location: string | null }) =>
        profiles(token).profiles_Update(body),
      changeHandle: (token: string, handle: string) => profiles(token).profiles_ChangeHandle({ handle }),
      setAvatar: (token: string, mediaId: string | null) => profiles(token).profiles_SetAvatar({ mediaId }),
      handleAvailability: (handle: string) => profiles(null).profiles_CheckHandle(handle),
      blocks: (token: string) => profiles(token).profiles_ListBlocks(),
      block: (token: string, user: string) => profiles(token).profiles_Block(user),
      unblock: (token: string, user: string) => profiles(token).profiles_Unblock(user),
      follow: (token: string, user: string) => profiles(token).profiles_Follow(user),
      unfollow: (token: string, user: string) => profiles(token).profiles_Unfollow(user),
      /** Who to follow: adults whose home area is near yours. */
      suggestions: (token: string, limit = 3) => profiles(token).profiles_Suggestions(limit),
      followers: (token: string | null, handle: string, page = 1) =>
        profiles(token).profiles_Followers(handle, page, 20),
      following: (token: string | null, handle: string, page = 1) =>
        profiles(token).profiles_Following(handle, page, 20),
    },
    timelines: {
      /** For you: anyone; ranked, and boosted near the signed-in user's home area. */
      forYou: (token: string | null, page = 1) =>
        client(TimelinesClient, { token }).timelines_ForYou(page, 20),
      following: (token: string, page = 1) =>
        client(TimelinesClient, { token }).timelines_Following(page, 20),
      list: (token: string) => client(TimelinesClient, { token }).timelines_List(),
      create: (token: string, body: TimelineRequest) =>
        client(TimelinesClient, { token }).timelines_Create(body),
      update: (token: string, id: string, body: TimelineRequest) =>
        client(TimelinesClient, { token }).timelines_Update(id, body),
      remove: (token: string, id: string) => client(TimelinesClient, { token }).timelines_Delete(id),
      reorder: (token: string, ids: string[]) =>
        client(TimelinesClient, { token }).timelines_Reorder({ ids }),
      posts: (token: string, id: string, page = 1) =>
        client(TimelinesClient, { token }).timelines_Posts(id, page, 20),
    },
    media: {
      requestUpload: (token: string, body: { fileName: string; contentType: string; sizeBytes: number }) =>
        client(MediaClient, { token }).media_RequestUpload(body),
      complete: (token: string, mediaId: string) => client(MediaClient, { token }).media_Complete(mediaId),
      get: (token: string, mediaId: string) => client(MediaClient, { token }).media_Get(mediaId),
      remove: (token: string, mediaId: string) => client(MediaClient, { token }).media_Delete(mediaId),
      /** Your video's vertical copy for TikTok, Reels, Shorts and X: its state, and a download link once made. */
      shareCopy: (token: string, mediaId: string) => client(MediaClient, { token }).media_GetShareCopy(mediaId),
      /** Ask for your video's vertical copy (made by the media worker); poll `shareCopy` until it's Ready. */
      requestShareCopy: (token: string, mediaId: string) =>
        client(MediaClient, { token }).media_RequestShareCopy(mediaId),
    },
    reels: {
      /** A page of reels. Logged-out viewers are counted by their viewer id. */
      list: (
        token: string | null,
        viewerId: string | null,
        q: { cursor?: string | null; category?: IncidentCategory; pageSize?: number } = {},
      ) =>
        client(ReelsClient, { token, headers: viewer(viewerId) }).reels_List(
          q.cursor,
          q.category,
          q.pageSize,
        ),
      /** Report that a reel has been watched for 3 seconds. Idempotent per viewer, reel and day. */
      play: (token: string | null, viewerId: string | null, postId: string) =>
        client(ReelsClient, { token, headers: viewer(viewerId) }).reels_Play(postId),
    },
    heatmap: {
      get: (token: string, q: HeatmapQuery) =>
        client(HeatmapClient, { token }).heatmap_Get(
          q.bbox,
          q.zoom,
          q.from,
          q.to,
          q.categories,
          q.hours,
          q.days,
          q.vehicleTypes,
          q.make,
          q.model,
          q.colours,
          q.light,
          q.schoolRun,
          q.reported,
          q.videoOnly,
        ),
      area: (token: string, q: HeatmapQuery) =>
        client(HeatmapClient, { token }).heatmap_Area(
          q.bbox,
          q.from,
          q.to,
          q.categories,
          q.hours,
          q.days,
          q.vehicleTypes,
          q.make,
          q.model,
          q.colours,
          q.light,
          q.schoolRun,
          q.reported,
          q.videoOnly,
        ),
    },
    trends: {
      /**
       * Category trends for the right panel. Anyone can call it; signed-out answers are the same for everyone, so they
       * can be cached for five minutes.
       */
      categories: (token: string | null, q: { from?: string; to?: string; bbox?: string } = {}) =>
        client(TrendsClient, { token, revalidate: 300 }).trends_Categories(q.from, q.to, q.bbox),
      /** Trending hashtags and towns (the same for everyone; cached for two minutes). */
      trending: () => client(TrendsClient, { token: null, revalidate: 120 }).trends_Trending(),
    },
    hashtags: {
      /** Tags starting with what's been typed after the #, most used first. */
      suggest: (prefix: string, limit = 8) =>
        client(HashtagsClient, { token: null, revalidate: 60 }).hashtags_Suggest(prefix, limit),
      /** A tag for its page (404 if no post has used it). */
      get: (tag: string) => client(HashtagsClient, { token: null, revalidate: 60 }).hashtags_Get(tag),
    },
    me: {
      /** Everything core holds about the user (profile, posts, comments, reactions, reports, media). */
      dataExport: async (token: string): Promise<unknown> => {
        // The generated method doesn't return the body (the endpoint streams a file), so read it here.
        const response = await api
          .http({ token })
          .fetch(`${api.baseUrl}/api/me/data-export`, { method: "GET" });
        return response.json();
      },
    },
    vehicles: {
      catalogue: () => client(VehiclesClient, { revalidate: 86_400 }).vehicles_Get(),
    },
    places: {
      search: (token: string, q: string) => client(PlacesClient, { token }).places_Search(q),
    },
    notifications: {
      list: (token: string, page = 1, pageSize = 20) =>
        client(NotificationsClient, { token }).notifications_List(page, pageSize),
      unreadCount: (token: string) => client(NotificationsClient, { token }).notifications_UnreadCount(),
      markRead: (token: string, ids: string[] | null) =>
        client(NotificationsClient, { token }).notifications_MarkRead({ ids }),
      settings: (token: string) => client(NotificationsClient, { token }).notifications_Settings(),
      area: (token: string) => client(AreaClient, { token }).area_Get(),
      setHomeArea: (token: string, place: { placeName: string; latitude: number; longitude: number }) =>
        client(AreaClient, { token }).area_SetHome(place),
      setAreaAlerts: (
        token: string,
        alerts: { enabled: boolean; radiusKm: number; mode: AreaAlertMode; email: boolean },
      ) => client(AreaClient, { token }).area_SetAlerts(alerts),
      clearHomeArea: (token: string) => client(AreaClient, { token }).area_Clear(),
      updateSettings: (token: string, settings: NotificationSettingDto[]) =>
        client(NotificationsClient, { token }).notifications_UpdateSettings({
          settings: settings.map(({ type, inApp, email, push }) => ({ type, inApp, email, push })),
        }),
      /** Whether web push is available, and the key browsers subscribe with. */
      pushSetup: (token: string) => client(NotificationsClient, { token }).notifications_PushSetup(),
      subscribePush: (token: string, subscription: { endpoint: string; p256dh: string; auth: string }) =>
        client(NotificationsClient, { token }).notifications_Subscribe(subscription),
      unsubscribePush: (token: string, endpoint: string) =>
        client(NotificationsClient, { token }).notifications_Unsubscribe({ endpoint }),
    },
  };
}

export type Endpoints = ReturnType<typeof endpoints>;
